/* ============================================================
   语音消息美化（透明水滴 + 纯播放键 + 去波形 + 展开自适应）
   ============================================================ */

/* 1. 外层气泡：改为 min-height，让它能随转文字内容自动撑高 */
.msg-voice-wrapper,
.voice-bubble-custom,
.msg-bubble-wrapper .bubble-me-custom:has(.voice-play-btn),
