  max-width: 65% !important;   
  padding: 0 14px !important; 
  min-height: 42px !important; /* 关键修改：把固定高度改为最小高度 */
  height: auto !important;     /* 关键修改：允许高度自适应 */
  display: inline-flex !important;
  flex-direction: column !important;
  justify-content: center !important; 
  align-items: center !important;
  gap: 0 !important;
  box-sizing: border-box !important;
}

/* 2. 内部布局：整体往上移 + 往左移 */
.voice-controls-row {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important; 
  width: 100% !important;
  min-height: 42px !important; /* 保证播放键这一行本身有足够高度 */
  height: auto !important;
  margin: 0 !important;
  padding: 0 0 0 8px !important; 
  transform: translateY(-2px) !important; 
}

/* 3. 播放键（透明水滴质感） */
.voice-play-btn, [class*="voice-play"] {
  width: 26px !important;
  height: 26px !important;
  min-width: 26px !important;
  min-height: 26px !important;
  flex-shrink: 0 !important;
  margin: 0 10px 0 0 !important; 
  border: 1px solid rgba(255,255,255,0.9) !important;
  border-radius: 50% !important;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,0.85) 0%,
    rgba(255,255,255,0.55) 55%,
    rgba(255,255,255,0.45) 100%
  ) !important;
  -webkit-backdrop-filter: blur(10px) saturate(160%) !important;
  backdrop-filter: blur(10px) saturate(160%) !important;
  box-shadow:
    inset 0 1px 1px rgba(255,255,255,0.95),
    inset 0 -2px 3px rgba(255,255,255,0.25),
    0 2px 6px rgba(255,255,255,0.2) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;
  filter: none !important;
}

/* 隐藏原图标 */
.voice-play-btn svg, [class*="voice-play"] svg { display: none !important; }

/* 播放三角形（纯 CSS） */
.voice-play-btn::before,
[class*="voice-play"]::before {
  content: "" !important;
  display: block !important;
  width: 0 !important;
  height: 0 !important;
  border-style: solid !important;
  border-width: 5px 0 5px 8px !important;
  border-color: transparent transparent transparent #333 !important;
  margin-left: 2px !important;
  z-index: 2 !important;
}

/* 暂停态：两根竖条 */
.voice-play-btn.is-playing::before,
[class*="voice-play"].is-playing::before,
.voice-play-btn[data-playing="true"]::before,
[class*="voice-play"][data-playing="true"]::before {
  content: "" !important;
  width: 7px !important;
  height: 9px !important;
  border: none !important;
  margin-left: 0 !important;
  background:
    linear-gradient(#333, #333) left / 2.5px 100% no-repeat,
    linear-gradient(#333, #333) right / 2.5px 100% no-repeat !important;
}

/* 4. 数字时间 */
.voice-duration {
  flex-shrink: 0 !important;
  margin: 0 !important; 
  font-size: 14px !important;
  font-weight: 900 !important;
  color: #333 !important;
  white-space: nowrap !important; 
}

/* 5. 波形（已彻底隐藏） */
.voice-waveform-container,
[class*="waveform-container"],
[class*="voice-wave"],
.voice-waveform-bar {
  display: none !important;
}

/* 6. 转写按钮：限制高度，不占用展开后的空间 */
.voice-transcription-toggle {
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  margin: 0 !important;
  padding: 0 !important;
  display: block !important;
  position: absolute !important; 
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 42px !important; /* 关键修改：限制点击热区高度为气泡初始高度，不覆盖下面展开的文字 */
  z-index: 10 !important;
  cursor: pointer !important;
  overflow: hidden !important;
}
.voice-transcription-toggle svg { display: none !important; }
.voice-transcription-toggle::before { content: none !important; }

/* 7. 下载按钮隐藏 */
