/* ============================================================
   转账卡片 —— 创意A：极简纯水珠 (自然流排版修复版)
   ============================================================ */

/* 1. 卡片外壳：定死尺寸、水珠质感、留出左侧图标空间 */
.msg-transfer-card {
  width: 250px !important;        
  height: 74px !important;        
  min-height: 74px !important;
  max-height: 74px !important;

  background: rgba(255, 255, 255, 0.05) !important; 
