  width: 100% !important;
  height: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  gap: 4px !important; /* 三行文字之间的间距 */
}

/* 5. 强制所有文字：取消绝对定位，按顺序排好，绝不重叠 */
.msg-transfer-card [class*="transfer-subtitle"],
.msg-transfer-card [class*="transfer-amount"],
.msg-transfer-card [class*="transfer-expire"],
.msg-transfer-card [class*="transfer-time"] {
